CREATE TABLE analyses (id UUID PRIMARY KEY, repository_url VARCHAR(500) NOT NULL, repository_owner VARCHAR(100) NOT NULL, repository_name VARCHAR(100) NOT NULL, reference VARCHAR(255), language VARCHAR(32) NOT NULL, files_analyzed INTEGER NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE findings (id UUID PRIMARY KEY, analysis_id UUID NOT NULL REFERENCES analyses(id) ON DELETE CASCADE, rule_id VARCHAR(32) NOT NULL, title VARCHAR(200) NOT NULL, severity VARCHAR(16) NOT NULL, cwe VARCHAR(32) NOT NULL, description VARCHAR(500) NOT NULL, file_name VARCHAR(1000) NOT NULL, line INTEGER NOT NULL, column_number INTEGER NOT NULL, snippet TEXT NOT NULL);
